/* ---------------------------------------------------------
   TFAM Insurance Surveyors & Loss Assessors Pvt. Ltd.
   Single-file corporate site (all real company content).

   Logo, director photos, and other real imagery are wired up
   via self-healing <img> components that load from
   /public/assets/images/ and fall back to an embedded copy of
   the exact uploaded file if that path is ever unavailable.
   Remaining site/inspection photography (About, Industries,
   Drone sections) uses labeled placeholder panels pending
   final photo assets from the client.
--------------------------------------------------------- */

const NAVY = "#0B3C5D";
const ROYAL = "#1E5AA8";
const GOLD = "#D4AF37";

/* ---------------------------------------------------------
   OFFICIAL TFAM LOGO
   Primary source: /assets/images/tfam-logo.jpeg
   Place the uploaded logo file at that path in your project's
   /public/assets/images/ directory (a copy is included in the
   delivered output folder alongside this file).

   LOGO_B64 below is the exact uploaded logo file, embedded as a
   data URI. It is used as a guaranteed last-resort fallback so
   the real logo ALWAYS renders even if the file path above is
   ever wrong, missing, or not yet deployed — no placeholder is
   ever shown.
--------------------------------------------------------- */
const LOGO_B64 =
  "data:image/jpeg;base64,";

// Common paths the logo might live at across typical project setups.
// The <Logo> component tries these in order before falling back to LOGO_B64.
const LOGO_CANDIDATES = [
  "/assets/images/tfam-logo.jpeg",
  "/assets/images/tfam-logo.png",
  "/images/tfam-logo.jpeg",
  "/logo.jpeg",
  "/logo.png",
];

function Logo({ className = "", alt = "TFAM Insurance Surveyors & Loss Assessors logo", ...rest }) {
  const [srcIndex, setSrcIndex] = useState(0);
  const [useFallback, setUseFallback] = useState(false);

  const handleError = () => {
    if (srcIndex < LOGO_CANDIDATES.length - 1) {
      setSrcIndex((i) => i + 1);
    } else {
      // All known paths failed — self-heal by using the embedded
      // copy of the actual logo file so it still displays correctly.
      setUseFallback(true);
    }
  };

  return (
    <img
      src={useFallback ? LOGO_B64 : LOGO_CANDIDATES[srcIndex]}
      onError={handleError}
      alt={alt}
      className={className}
      {...rest}
    />
  );
}

/* ---------------------------------------------------------
   DIRECTOR PHOTOS (uploaded originals — real photographs,
   no placeholders, no stock/AI images)
   Primary source paths: /assets/images/director-*.jpeg
   Copies are included in the delivered output folder for you
   to drop into /public/assets/images/ in your project.

   Each director's photo is also embedded below as a base64
   data URI. This is the guaranteed final fallback: if the file
   path is ever wrong, missing, or not yet deployed, the exact
   uploaded photo still renders instead of a broken image icon.
--------------------------------------------------------- */
const DIRECTOR_PHOTOS = {
  "raja-thiraviya-kumar": {
    candidates: [
      "/assets/images/director-raja-thiraviya-kumar.jpeg",
      "/assets/images/director-raja-thiraviya-kumar.jpg",
      "/images/director-raja-thiraviya-kumar.jpeg",
    ],
    fallback: "data:image/jpeg;base64,",
  },
  "raja-naren": {
    candidates: [
      "/assets/images/director-raja-naren.jpeg",
      "/assets/images/director-raja-naren.jpg",
      "/images/director-raja-naren.jpeg",
    ],
    fallback: "data:image/jpeg;base64,",
  },
};

function DirectorPhoto({ photoId, alt, className = "" }) {
  const entry = DIRECTOR_PHOTOS[photoId];
  const [srcIndex, setSrcIndex] = useState(0);
  const [useFallback, setUseFallback] = useState(false);

  if (!entry) return null;

  const handleError = () => {
    if (srcIndex < entry.candidates.length - 1) {
      setSrcIndex((i) => i + 1);
    } else {
      // Every known path failed — self-heal with the embedded
      // copy of this director's actual uploaded photo.
      setUseFallback(true);
    }
  };

  return (
    <img
      src={useFallback ? entry.fallback : entry.candidates[srcIndex]}
      onError={handleError}
      alt={alt}
      loading="lazy"
      decoding="async"
      className={className}
    />
  );
}

function useReveal() {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) { setVisible(true); obs.disconnect(); } },
      { threshold: 0.15 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return [ref, visible];
}

function Reveal({ children, delay = 0, className = "" }) {
  const [ref, visible] = useReveal();
  return (
    <div
      ref={ref}
      className={className}
      style={{
        opacity: visible ? 1 : 0,
        transform: visible ? "translateY(0)" : "translateY(28px)",
        transition: `opacity 0.7s ease ${delay}ms, transform 0.7s cubic-bezier(0.16,1,0.3,1) ${delay}ms`,
      }}
    >
      {children}
    </div>
  );
}

function Counter({ end, suffix = "", duration = 1800 }) {
  const [ref, visible] = useReveal();
  const [val, setVal] = useState(0);
  useEffect(() => {
    if (!visible) return;
    let start = null;
    const step = (ts) => {
      if (!start) start = ts;
      const progress = Math.min((ts - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setVal(Math.floor(eased * end));
      if (progress < 1) requestAnimationFrame(step);
      else setVal(end);
    };
    requestAnimationFrame(step);
  }, [visible, end, duration]);
  return <span ref={ref}>{val.toLocaleString()}{suffix}</span>;
}

