/* ---------------------- Header ---------------------- */
/* ---------------------------------------------------------
   In-page navigation helpers
   - NAV_LINKS is the single source of truth for every menu
     item's label and target section id, so the menu can never
     drift out of sync with the actual <section id="..."> tags.
   - scrollToId() smooth-scrolls to a section while compensating
     for the fixed header's height, so sections never end up
     hidden underneath it.
--------------------------------------------------------- */
const NAV_LINKS = [
  { label: "Home", id: "home" },
  { label: "About", id: "about" },
  { label: "Services", id: "services" },
  { label: "Industries", id: "industries" },
  { label: "Drone Imaging", id: "drone-imaging" },
  { label: "Leadership", id: "leadership" },
  { label: "Contact", id: "contact" },
];

const HEADER_OFFSET = 96;

function scrollToId(id) {
  const el = document.getElementById(id);
  if (!el) return;
  const top = el.getBoundingClientRect().top + window.pageYOffset - HEADER_OFFSET;
  window.scrollTo({ top: Math.max(top, 0), behavior: "smooth" });
  // Keep the URL hash in sync without triggering a jump/reload.
  if (window.history && window.history.replaceState) {
    window.history.replaceState(null, "", `#${id}`);
  }
}

function NavLink({ id, label, onNavigate, isActive, mobile = false, scrolled }) {
  const desktopClasses = scrolled
    ? isActive ? "text-[#0B3C5D]" : "text-gray-700 hover:text-[#0B3C5D]"
    : isActive ? "text-white" : "text-white/85 hover:text-white";

  return (
    <a
      href={`#${id}`}
      onClick={(e) => {
        e.preventDefault();
        onNavigate(id);
      }}
      aria-current={isActive ? "true" : undefined}
      className={
        mobile
          ? `block font-semibold text-base transition-colors ${isActive ? "text-[#0B3C5D]" : "text-gray-800 hover:text-[#0B3C5D]"}`
          : `relative text-sm font-semibold transition-colors ${desktopClasses}`
      }
    >
      {label}
      {!mobile && isActive && (
        <span
          className="absolute left-0 right-0 -bottom-2 h-0.5 rounded-full"
          style={{ background: GOLD }}
        />
      )}
    </a>
  );
}

function Header() {
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [activeId, setActiveId] = useState("home");

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  // Track which section is currently in view so the matching nav
  // item can be highlighted automatically as the user scrolls.
  useEffect(() => {
    const sections = NAV_LINKS
      .map((l) => document.getElementById(l.id))
      .filter(Boolean);
    if (sections.length === 0) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) setActiveId(entry.target.id);
        });
      },
      { rootMargin: `-${HEADER_OFFSET + 8}px 0px -55% 0px`, threshold: 0 }
    );
    sections.forEach((s) => observer.observe(s));
    return () => observer.disconnect();
  }, []);

  const handleNavigate = (id) => {
    setOpen(false);
    setActiveId(id);
    // Let the mobile menu close first, then scroll, so the layout
    // shift from closing the menu doesn't throw off the offset.
    window.setTimeout(() => scrollToId(id), open ? 60 : 0);
  };

  return (
    <header
      className="fixed top-0 left-0 right-0 z-50 transition-all duration-300"
      style={{
        background: scrolled ? "#FFFFFF" : "rgba(11,60,93,0.0)",
        boxShadow: scrolled ? "0 1px 0 rgba(0,0,0,0.06), 0 8px 24px rgba(11,60,93,0.06)" : "none",
      }}
    >
      <div className={`transition-all duration-300 ${scrolled ? "bg-white" : ""}`}>
        <div className="max-w-7xl mx-auto px-6 flex items-center justify-between" style={{ height: scrolled ? "72px" : "88px" }}>
          <a
            href="#home"
            onClick={(e) => { e.preventDefault(); handleNavigate("home"); }}
            className="flex items-center gap-3"
            aria-label="TFAM — go to homepage"
          >
            <Logo className="h-11 w-11 rounded-lg bg-white p-1 object-contain shadow-sm" />
            <div className="leading-tight">
              <p className={`font-extrabold text-lg tracking-tight ${scrolled ? "" : "text-white"}`} style={scrolled ? { color: NAVY } : {}}>TFAM</p>
              <p className={`text-[10px] font-semibold tracking-widest uppercase ${scrolled ? "text-gray-500" : "text-white/60"}`}>Insurance Surveyors &amp; Loss Assessors</p>
            </div>
          </a>

          <nav className="hidden lg:flex items-center gap-8">
            {NAV_LINKS.map((l) => (
              <NavLink
                key={l.id}
                id={l.id}
                label={l.label}
                onNavigate={handleNavigate}
                isActive={activeId === l.id}
                scrolled={scrolled}
              />
            ))}
          </nav>

          <div className="hidden lg:flex items-center gap-3">
            <a href="tel:+919443433534" className={`text-sm font-bold flex items-center gap-2 ${scrolled ? "text-[#0B3C5D]" : "text-white"}`}>
              <Phone size={16} /> +91 94434 33534
            </a>
            <a
              href="#contact"
              onClick={(e) => { e.preventDefault(); handleNavigate("contact"); }}
              className="px-5 py-2.5 rounded-lg text-sm font-bold text-white transition-transform hover:-translate-y-0.5"
              style={{ background: NAVY }}
            >
              Request a Survey
            </a>
          </div>

          <button
            className={`lg:hidden ${scrolled ? "text-[#0B3C5D]" : "text-white"}`}
            onClick={() => setOpen((o) => !o)}
            aria-label={open ? "Close menu" : "Open menu"}
            aria-expanded={open}
          >
            {open ? <X size={26} /> : <Menu size={26} />}
          </button>
        </div>
      </div>

      {open && (
        <div className="lg:hidden bg-white border-t border-gray-100 px-6 py-6 space-y-4">
          {NAV_LINKS.map((l) => (
            <NavLink
              key={l.id}
              id={l.id}
              label={l.label}
              onNavigate={handleNavigate}
              isActive={activeId === l.id}
              mobile
            />
          ))}
          <a
            href="#contact"
            onClick={(e) => { e.preventDefault(); handleNavigate("contact"); }}
            className="block text-center px-5 py-3 rounded-lg text-sm font-bold text-white"
            style={{ background: NAVY }}
          >
            Request a Survey
          </a>
        </div>
      )}
    </header>
  );
}

